CREATE TABLE `deliveryreceiptdetail` (
  `DRDetailID` int(11) NOT NULL AUTO_INCREMENT,
  `DRID` int(11) NOT NULL,
  `ArticleID` bigint(20) unsigned DEFAULT NULL,
  `ItemDescription` varchar(255) NOT NULL COMMENT 'Manual item description',
  `Brand` varchar(100) DEFAULT NULL,
  `ModelNumber` varchar(100) DEFAULT NULL,
  `SerialNumber` varchar(100) DEFAULT NULL,
  `PropertyTypeID` int(11) NOT NULL,
  `QuantityDelivered` int(11) NOT NULL,
  `QuantityRequested` int(11) DEFAULT NULL,
  `ChangeReason` varchar(255) DEFAULT NULL,
  `UnitOfMeasureID` int(11) NOT NULL DEFAULT 1,
  `UnitCost` decimal(18,2) DEFAULT NULL,
  `TotalCost` decimal(18,2) DEFAULT NULL,
  `InspectionStatus` enum('pending','inspected') NOT NULL DEFAULT 'pending',
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`DRDetailID`),
  KEY `DRID` (`DRID`),
  KEY `PODetailID` (`ItemDescription`),
  KEY `PropertyTypeID` (`PropertyTypeID`),
  KEY `UnitOfMeasureID` (`UnitOfMeasureID`),
  KEY `deliveryreceiptdetail_articleid_index` (`ArticleID`),
  KEY `drdetail_id_idx` (`DRDetailID`),
  CONSTRAINT `deliveryreceiptdetail_articleid_foreign` FOREIGN KEY (`ArticleID`) REFERENCES `articles` (`ArticleID`) ON DELETE SET NULL,
  CONSTRAINT `deliveryreceiptdetail_ibfk_1` FOREIGN KEY (`DRID`) REFERENCES `deliveryreceipt` (`DRID`),
  CONSTRAINT `deliveryreceiptdetail_ibfk_3` FOREIGN KEY (`PropertyTypeID`) REFERENCES `propertytype` (`PropertyTypeID`),
  CONSTRAINT `fk_drdetail_unitofmeasure` FOREIGN KEY (`UnitOfMeasureID`) REFERENCES `unitofmeasure` (`UnitOfMeasureID`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=205 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
