CREATE TABLE `propertyissuancedetail` (
  `IssuanceDetailID` int(11) NOT NULL AUTO_INCREMENT,
  `IssuanceID` int(11) NOT NULL,
  `RequestDetailID` bigint(20) unsigned DEFAULT NULL,
  `ris_item_id` bigint(20) unsigned DEFAULT NULL,
  `ItemDescription` varchar(255) DEFAULT NULL,
  `Unit` varchar(50) DEFAULT NULL,
  `InventoryDetailID` int(11) DEFAULT NULL,
  `QuantityIssued` int(11) NOT NULL,
  `Remarks` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`IssuanceDetailID`),
  KEY `IssuanceID` (`IssuanceID`),
  KEY `InventoryDetailID` (`InventoryDetailID`),
  KEY `propertyissuancedetail_requestdetailid_foreign` (`RequestDetailID`),
  KEY `propertyissuancedetail_ris_item_id_index` (`ris_item_id`),
  KEY `pidet_inventory_deleted_issuance_idx` (`InventoryDetailID`,`deleted_at`,`IssuanceID`),
  KEY `pidet_invdetail_deleted_idx` (`InventoryDetailID`,`deleted_at`),
  CONSTRAINT `propertyissuancedetail_ris_item_id_foreign` FOREIGN KEY (`ris_item_id`) REFERENCES `requisition_issue_slip_items` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=246 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
