  `closed_at` datetime DEFAULT NULL,
  `closed_by_user_id` int(11) DEFAULT NULL,
  `reopened_at` datetime DEFAULT NULL,
  `reopen_reason` text DEFAULT NULL,
  `reopen_count` int(10) unsigned NOT NULL DEFAULT 0,
  `close_reason` text DEFAULT NULL,
  `created_by_user_id` int(11) NOT NULL,
  `updated_by_user_id` int(11) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `reopened_by_user_id` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `rpc_inventory_cycles_cycle_label_unique` (`cycle_label`),
  UNIQUE KEY `rpc_inventory_cycles_start_year_unique` (`start_year`),
  KEY `rpc_inventory_cycles_status_index` (`status`),
  KEY `rpc_inventory_cycles_created_by_user_id_foreign` (`created_by_user_id`),
  KEY `rpc_inventory_cycles_updated_by_user_id_foreign` (`updated_by_user_id`),
  KEY `rpc_inventory_cycles_closed_by_at_index` (`closed_at`),
  KEY `rpc_inventory_cycles_reopened_by_at_index` (`reopened_at`),
  KEY `rpc_inventory_cycles_closed_by_user_id_foreign` (`closed_by_user_id`),
  KEY `rpc_inventory_cycles_reopened_by_user_id_foreign` (`reopened_by_user_id`),
  CONSTRAINT `rpc_inventory_cycles_closed_by_user_id_foreign` FOREIGN KEY (`closed_by_user_id`) REFERENCES `user` (`UserID`) ON DELETE SET NULL,
  CONSTRAINT `rpc_inventory_cycles_created_by_user_id_foreign` FOREIGN KEY (`created_by_user_id`) REFERENCES `user` (`UserID`),
  CONSTRAINT `rpc_inventory_cycles_reopened_by_user_id_foreign` FOREIGN KEY (`reopened_by_user_id`) REFERENCES `user` (`UserID`) ON DELETE SET NULL,
  CONSTRAINT `rpc_inventory_cycles_updated_by_user_id_foreign` FOREIGN KEY (`updated_by_user_id`) REFERENCES `user` (`UserID`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
